import{_ as n,a0 as i,w as u,s as l,ao as r,I as p,x as a,a1 as s,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"如何在 Ubuntu 服務器中配置 AWStats | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 服務器中配置 AWStats | LCTT (201512) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 服務器中配置 AWStats | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 服務器中配置 AWStats | LCTT (201512) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201512/20151109 How to Set Up AWStats On Ubuntu Server","title":"如何在 Ubuntu 服務器中配置 AWStats","tag":"201512","desc":""},"relativePath":"201512/20151109 How to Set Up AWStats On Ubuntu Server.md","filePath":"[post].md"}'),d={name:"201512/20151109 How to Set Up AWStats On Ubuntu Server.md"};function w(h,t,c,m,b,S){const e=i("Link");return u(),l("div",null,[t[16]||(t[16]=r(`<h1 id="如何在-ubuntu-服務器中配置-awstats" tabindex="-1">如何在 Ubuntu 服務器中配置 AWStats <a class="header-anchor" href="#如何在-ubuntu-服務器中配置-awstats" aria-label="Permalink to “如何在 Ubuntu 服務器中配置 AWStats”">​</a></h1><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/Apache_awstats_featured.jpg" alt=""></p><p>AWStats 是一個開源的網站分析報告工具，可以生成強大的網站、流媒體、FTP 或郵件服務器的訪問統計圖。此日誌分析器以 CGI 或命令列方式進行工作，並在網頁中以圖表的形式儘可能的顯示你日誌中所有的信息。它可以“部分”讀取信息文件，以便能夠頻繁並快速處理大量的日誌文件。它支持絕大多數 Web 服務器日誌文件格式，包括 Apache，IIS 等。</p><p>本文將幫助你在 Ubuntu 上安裝配置 AWStats。</p><h3 id="安裝-awstats-包" tabindex="-1">安裝 AWStats 包 <a class="header-anchor" href="#安裝-awstats-包" aria-label="Permalink to “安裝 AWStats 包”">​</a></h3><p>默認情況下，AWStats 的包可以在 Ubuntu 倉庫中找到。</p><p>可以通過運行下面的命令來安裝：</p><pre><code>sudo apt-get install awstats
</code></pre><p>接下來，你需要啓用 Apache 的 CGI 模組。</p><p>運行以下命令來啓動 CGI：</p><pre><code>sudo a2enmod cgi
</code></pre><p>現在，重新啓動 Apache 以使改變生效。</p><pre><code>sudo /etc/init.d/apache2 restart
</code></pre><h3 id="配置-awstats" tabindex="-1">配置 AWStats <a class="header-anchor" href="#配置-awstats" aria-label="Permalink to “配置 AWStats”">​</a></h3><p>你需要為你想要查看統計的每個域或網站創建一個配置文件。在這個例子中，我們將為 “test.com” 創建一個配置文件。</p><p>要完成此步，你可以通過複製 AWStats 的默認配置文件來配置你要統計的域。</p><pre><code>sudo cp /etc/awstats/awstats.conf /etc/awstats/awstats.test.com.conf
</code></pre><p>現在，你需要在配置文件中做一些修改：</p><pre><code>sudo nano /etc/awstats/awstats.test.com.conf
</code></pre><p>像下面這樣修改一下:</p><pre><code># Change to Apache log file, by default it&#39;s /var/log/apache2/access.log
LogFile=&quot;/var/log/apache2/access.log&quot;
 
# Change to the website domain name
SiteDomain=&quot;test.com&quot;
HostAliases=&quot;www.test.com localhost 127.0.0.1&quot;
 
# When this parameter is set to 1, AWStats adds a button on report page to allow to &quot;update&quot; statistics from a web browser
AllowToUpdateStatsFromBrowser=1
</code></pre><p>保存並關閉文件。</p><p>修改配置文件後，你需要用服務器的當前日誌建立初步統計。你可以這樣做：</p><pre><code>sudo /usr/lib/cgi-bin/awstats.pl -config=test.com -update
</code></pre><p>輸出會是這個樣子:</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/awtstats.png" alt="awtstats"></p><h3 id="為-apache-配置-awstats" tabindex="-1">為 Apache 配置 AWStats <a class="header-anchor" href="#為-apache-配置-awstats" aria-label="Permalink to “為 Apache 配置 AWStats”">​</a></h3><p>接下來，你需要配置 Apache2 來顯示統計數據。現在你需要將 “cgi-bin” 文件夾中的內容複製到 Apache 默認根目錄下。默認它是在 “/usr/lib/cgi-bin”。</p><p>運行以下命令來完成此步:</p><pre><code>sudo cp -r /usr/lib/cgi-bin /var/www/html/
sudo  chown www-data:www-data /var/www/html/cgi-bin/
sudo chmod -R 755 /var/www/html/cgi-bin/
</code></pre><h3 id="測試-awstats" tabindex="-1">測試 AWStats <a class="header-anchor" href="#測試-awstats" aria-label="Permalink to “測試 AWStats”">​</a></h3>`,31)),p("p",null,[t[1]||(t[1]=a("現在，您可以通過訪問 url “",-1)),s(e,{href:"http://your-server-ip/cgi-bin/awstats.pl?config=test.com.%E2%80%9D"},{default:o(()=>[...t[0]||(t[0]=[a("http://your-server-ip/cgi-bin/awstats.pl?config=test.com.”",-1)])]),_:1}),t[2]||(t[2]=a(" 來查看 AWStats 的頁面。",-1))]),t[17]||(t[17]=r(`<p>它的頁面像下面這樣：</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/awstats_page.jpg" alt="awstats_page"></p><h3 id="設置定時任務來更新日誌" tabindex="-1">設置定時任務來更新日誌 <a class="header-anchor" href="#設置定時任務來更新日誌" aria-label="Permalink to “設置定時任務來更新日誌”">​</a></h3><p>建議你創建一個定時任務，使用新創建的日誌條目定期更新 AWStats 的資料庫，然後統計會定期更新。這也將節省你的時間。</p><p>要做到這一點，你需要編輯 “/etc/crontab” 文件:</p><pre><code>sudo nano /etc/crontab
</code></pre><p>添加下面那一行來讓 AWStats 每十分鐘更新一次。</p><pre><code>*/10 * * * * root /usr/lib/cgi-bin/awstats.pl -config=test.com -update
</code></pre><p>保存並關閉文件。</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>AWStats 是一個非常有用的工具，可以讓你對網站的狀況瞭如指掌，並能協助你分析網站。它非常容易安裝和配置。如果你有任何疑問，請在下面發表評論。</p><hr>`,12)),p("p",null,[t[4]||(t[4]=a("via: ",-1)),s(e,{href:"https://www.maketecheasier.com/set-up-awstats-ubuntu/"},{default:o(()=>[...t[3]||(t[3]=[a("https://www.maketecheasier.com/set-up-awstats-ubuntu/",-1)])]),_:1})]),p("p",null,[t[8]||(t[8]=a("作者：",-1)),s(e,{href:"https://www.maketecheasier.com/author/hiteshjethva/"},{default:o(()=>[...t[5]||(t[5]=[a("Hitesh Jethva",-1)])]),_:1}),t[9]||(t[9]=a(" 譯者：",-1)),s(e,{href:"https://github.com/strugglingyouth"},{default:o(()=>[...t[6]||(t[6]=[a("strugglingyouth",-1)])]),_:1}),t[10]||(t[10]=a(" 校對：",-1)),s(e,{href:"https://github.com/wxy"},{default:o(()=>[...t[7]||(t[7]=[a("wxy",-1)])]),_:1})]),p("p",null,[t[13]||(t[13]=a("本文由 ",-1)),s(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[11]||(t[11]=[a("LCTT",-1)])]),_:1}),t[14]||(t[14]=a(" 原創編譯，",-1)),s(e,{href:"https://linux.cn/"},{default:o(()=>[...t[12]||(t[12]=[a("Linux中國",-1)])]),_:1}),t[15]||(t[15]=a(" 榮譽推出",-1))])])}const T=n(d,[["render",w]]);export{f as __pageData,T as default};
